export function scaleForHeight(width: any, height: any, targetHeight: any, constraints?: {}): {
    height: number;
    width: number;
} | {
    height: null;
    width: null;
};
export function scaleForWidth(width: any, height: any, targetWidth: any, constraints?: {}): {
    height: number;
    width: number;
} | {
    height: null;
    width: null;
};
